( 

(floor(Thursday_Time_Out_Proxy__c) + (Thursday_Time_Out_Proxy__c- floor(Thursday_Time_Out_Proxy__c))/60*100)

- (floor(Thursday_Time_In_Proxy__c) + (Thursday_Time_In_Proxy__c- floor(Thursday_Time_In_Proxy__c))/60*100)

),

( 

(floor(Thursday_Lunch_Start_Proxy__c ) + (Thursday_Lunch_Start_Proxy__c - floor(Thursday_Lunch_Start_Proxy__c ))/60*100)

- (floor(Thursday_Time_In_Proxy__c) + (Thursday_Time_In_Proxy__c- floor(Thursday_Time_In_Proxy__c))/60*100)

)

))
